import assert from "node:assert/strict";
import { test } from "node:test";
import { TtlCache } from "../src/cache.ts";

test("entries live for the default ttl", () => {
  const cache = new TtlCache<string>("5m");
  cache.set("a", "value", undefined, 1_000);
  assert.equal(cache.get("a", 1_000 + 299_999), "value");
  assert.equal(cache.get("a", 1_000 + 300_000), undefined);
});

test("a ttl given to set wins over the default", () => {
  const cache = new TtlCache<number>("5m");
  cache.set("a", 1, "10s", 0);
  assert.equal(cache.get("a", 9_999), 1);
  assert.equal(cache.get("a", 10_000), undefined);
});
import assert from "node:assert/strict";
import { test } from "node:test";
import { backoffDelayMs, withRetry } from "../src/retry.ts";

test("the backoff delay doubles with every attempt", () => {
  assert.equal(backoffDelayMs("2s", 0), 2000);
  assert.equal(backoffDelayMs("2s", 1), 4000);
  assert.equal(backoffDelayMs("1m", 2), 240000);
});

test("withRetry sleeps between failed attempts and returns the first success", async () => {
  const sleeps: number[] = [];
  let calls = 0;
  const result = await withRetry(
    async () => {
      calls++;
      if (calls < 3) {
        throw new Error("flaky");
      }
      return "done";
    },
    { attempts: 5, backoff: "1s" },
    async (ms) => {
      sleeps.push(ms);
    },
  );
  assert.equal(result, "done");
  assert.deepEqual(sleeps, [1000, 2000]);
});

test("withRetry rethrows the last error once the attempts are used up", async () => {
  await assert.rejects(
    withRetry(
      async () => {
        throw new Error("down");
      },
      { attempts: 2, backoff: "1s" },
      async () => {},
    ),
    /down/,
  );
});
import assert from "node:assert/strict";
import { test } from "node:test";
import { dueJobs, nextRun } from "../src/scheduler.ts";

test("nextRun adds the interval to the last run", () => {
  assert.equal(nextRun({ name: "sync", every: "15m", lastRun: 1_000 }), 1_000 + 900_000);
});

test("dueJobs returns the jobs whose next run has been reached", () => {
  const jobs = [
    { name: "sync", every: "1m", lastRun: 0 },
    { name: "cleanup", every: "1h", lastRun: 0 },
  ];
  assert.deepEqual(
    dueJobs(jobs, 120_000).map((job) => job.name),
    ["sync"],
  );
});
